custom_fields.options:
{% if doc.critical_vital_respiratory_rate || doc.critical_vital_temperature || doc.critical_vital_heart_rate || doc.critical_vital_bpdiastolic || doc.critical_vital_bpsystolic || doc.critical_vital_oxygen_saturation %}
<h6 style="color: red;">CRITICAL VITALS</h6>
{% endif %}

<div class="form-row mb-3">
    {% if doc.critical_vital_temperature %}
    <div class="col-md-2 ">
             Temp: <span style="color: red; font-weight: bold;">{{ doc.critical_vital_temperature }}</span>
    </div>
    {% endif %}
    {% if doc.critical_vital_respiratory_rate %}
    <div class="col-md-2 ">
             Respiratory Rate: <span style="color: red; font-weight: bold;">{{ doc.critical_vital_respiratory_rate }}</span>
    </div>
    {% endif %}
    {% if doc.critical_vital_heart_rate %}
    <div class="col-md-2 ">
             Heart Rate: <span style="color: red; font-weight: bold;">{{ doc.critical_vital_heart_rate }}</span>
    </div>
    {% endif %}
    {% if doc.critical_vital_bpdiastolic %}
    <div class="col-md-2 ">
             BP Diastolic: <span style="color: red; font-weight: bold;">{{ doc.critical_vital_bpdiastolic }}</span>
    </div>
    {% endif %}
    {% if doc.critical_vital_bpsystolic %}
    <div class="col-md-2 ">
             BP Systolic: <span style="color: red; font-weight: bold;">{{ doc.critical_vital_bpsystolic }}</span>
    </div>
    {% endif %}
    {% if doc.critical_vital_oxygen_saturation %}
    <div class="col-md-2 ">
             Oxygen Saturation: <span style="color: red; font-weight: bold;">{{ doc.critical_vital_oxygen_saturation }}</span>
    </div>
    {% endif %}
    </div>
</div>
